pub(crate) async fn props_of(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    module: &Module,
    target: &Target,
) -> Result<Answer, CallError> {
    let (symbol, export) = match component_symbol(rpc, module, target).await? {
        Ok(found) => found,
        Err(reason) => return Ok(Answer::Fallback(reason)),
    };

    let component = rpc.type_of_symbol(&symbol.reference).await?;
    let signatures = rpc.signatures(component.id, SignatureKind::Call).await?;
    let [signature] = signatures.as_slice() else {
        return fallback(if signatures.is_empty() {
            "no call signature (class or non-function component)"
        } else {
            "overloaded call signatures"
        });
    };
    let parameters = rpc.parameters(signature.id).await?;
    let Some(first) = parameters.first() else { return fallback("takes no props parameter") };
    if let Some(arguments) = instantiate::default_arguments(rpc, signature).await? {
        if !export.members.is_empty() {
            return fallback("a generic sub-component reached through its parent's property is not instantiated");
        }
        return Ok(Answer::Instantiate(Instantiation { export: export.name, arguments }));
    }

    let props_type = rpc.type_of_symbol(&first.reference).await?;
    Ok(props_of_type(rpc, converter, interner, &props_type, target).await?.map_or_else(Answer::Fallback, Answer::Props))
}

/// The props a component's props type holds, or why the component keeps its structural result.
pub(crate) async fn props_of_type(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    props_type: &TypeInfo,
    target: &Target,
) -> Result<Result<Props, String>, CallError> {
    if props_type.flags & (flag::ANY | flag::UNKNOWN | flag::UNION | flag::TYPE_PARAMETER) != 0 {
        return Ok(Err("props type is any, unknown, generic or a union".to_string()));
    }

    let own: Vec<SymbolInfo> = rpc
        .properties(props_type.id)
        .await?
        .into_iter()
        .filter(|property| {
            !is_react_declared(property)
                || target.react_wanted.as_ref().is_none_or(|wanted| wanted.contains(&property.name))
        })
        .collect();
    let (own, layered) = leave_to_layers(converter, interner, own, target).await?;
    let references: Vec<_> = own.iter().map(|property| &property.reference).collect();
    let types = if references.is_empty() { Vec::new() } else { converter.types_of_symbols(&references).await? };

    // React's own descriptions and tags are the structural pass's to give, and its props are most of a component's.
    let asked: Vec<Asked<'_>> = own
        .iter()
        .map(|property| {
            let react_declared = is_react_declared(property);
            Asked {
                property,
                description: !react_declared && !target.described.contains(&property.name),
                tags: !react_declared,
            }
        })
        .collect();
    let keys: Vec<PropKey> = asked
        .iter()
        .zip(&types)
        .map(|(asked, prop_type)| PropKey::of(asked.property, prop_type, asked.description, asked.tags))
        .collect();
    let mut props: Vec<Option<Arc<SemanticProp>>> = keys.iter().map(|key| converter.known_prop(key)).collect();
    let missing: Vec<usize> = (0..props.len()).filter(|index| props.get(*index).is_some_and(Option::is_none)).collect();
    let unknown_types: Vec<TypeInfo> =
        missing.iter().filter_map(|index| types.get(*index).map(|info| TypeInfo::clone(info))).collect();
    let converted = converter.convert_roots(&unknown_types).await?;
    let unknown_asked: Vec<Asked<'_>> = missing
        .iter()
        .filter_map(|index| asked.get(*index))
        .map(|asked| Asked { property: asked.property, description: asked.description, tags: asked.tags })
        .collect();
    let declared = converter.declared(&unknown_asked).await?;
    let mut keys: Vec<Option<PropKey>> = keys.into_iter().map(Some).collect();
    for ((index, prop_type), declared) in missing.iter().zip(converted).zip(declared) {
        let (Some(property), Some(key)) = (own.get(*index), keys.get_mut(*index).and_then(Option::take)) else {
            continue;
        };
        let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
        let prop = interner.share(SemanticProp {
            name: property.name.clone(),
            prop_type: without_undefined(prop_type, !required),
            required,
            description: declared.description,
            tags: declared.tags,
            parent: declared.parent,
            declarations: declared.declarations,
            react_declared: is_react_declared(property),
        });
        converter.keep_prop(key, prop.clone());
        if let Some(slot) = props.get_mut(*index) {
            *slot = Some(prop);
        }
    }
    // In the props type's order: each converted prop in its place among those left to a layer.
    let mut converted = props.into_iter().flatten();
    let props: Vec<Arc<SemanticProp>> =
        layered.into_iter().filter_map(|slot| slot.or_else(|| converted.next())).collect();
    let composes = converter.composes(props_type).await?;

    /// is asked for every prop's description, [`SemanticTarget::described`] included: the merge keeps no structural
    /// description, so a prop the checker was not asked about would lose its own.
    pub fn ready(self, targets: &mut [SemanticTarget]) {
        if !self.falls_back() {
            for target in targets {
                target.described.clear();
            }
        }
    }
}

/// Replaces `entry`'s props and `composes` with the checker's, keeping a description or tags only the structural pass
/// has, for the whole-project merge. Facts are read as [`merge_semantic_props`] reads them, from `syntax` and as
/// `resolver` allows. The checker's props are laid out in the layers `cx` decides ([`layer_checker_props`]).
#[allow(clippy::too_many_arguments)]
fn apply_props(
    entry: &mut ComponentEntry,
    semantic: &SemanticComponent,
    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
    memo: &mut MergeMemo,
    syntax: &SourceSyntax,
    resolver: ResolverFacts,
    cx: CollapseContext,
) -> MergedProps {
    // The whole-project merge replaces the props and leaves `@types/react`'s to the inheritance layers. A component
    // with no layer has nowhere to leave them: a context's `Provider` (`value`, `children`) or a `th`/`td` attribute
    // intersection names no element. Its `@types/react` props the structural pass lists stay, as the curated mode
    // keeps them (`targets_of` asks the checker for those names only, `key` among them only if the component lists it).
    let layered = !entry.inheritance.is_empty();
    let own: Vec<&Arc<SemanticProp>> = semantic
        .props
        .iter()
        .filter(|prop| !prop.react_declared || (!layered && entry.props.contains_key(&prop.name)))
        .collect();
    let (own, notable) = layer_checker_props(entry, own, cx);
    let merge = Merge { composes: semantic.composes.as_deref(), unanswered: Unanswered::Drop, syntax, resolver };
    let merged = replace_props(entry, own.into_iter(), &merge, shared, memo);
    move_notable(entry, &notable);
    merged
}

/// The checker's `props` for `entry` without those an inherited source collapsed into a layer holds, and the notable
/// ones to move to `notableInherited` once merged ([`move_notable`]).
///
/// The collapse decision has one owner, [`CollapseInheritedProps::collapses`](crate::types::options::CollapseInheritedProps::collapses),
/// asked with the members of a source that reach the component. The structural resolver decides the sources it reads,
/// which are its layers here; a source the structural answer did not read (no structural prop and no layer has it as
/// its source) is decided by `cx` ([`CollapseContext::collapses`]). [`Layering::kept`] makes the same decision from a
/// [`LayerFacts`] of `entry`, before the answer's types are converted.
///
/// 1. A prop a collapsed layer names (`InheritedLayer::members`) is left to it, unless the structural answer lists the
///    prop itself (the component declares it again).
/// 2. A source only the checker read becomes a collapsed layer when the owner collapses it, asked with the members
///    that reach the component: the props of the answer whose `parent` is the source, after any `Omit` or `Pick`, each
///    name once (the structural resolver counts the same; no declared count is asked of the checker). `members` are those props and `totalProps` their number,
///    what the layer holds. Its notable props move to `notableInherited`, as the structural resolver keeps a collapsed
///    source's notable members.
///
/// Applying it again to the entry it changed gives the same props and layers: a layer made here is then a layer of the
/// entry, which the first rule follows.
pub(crate) fn layer_checker_props<'a>(
----
/// the structural `composes` ([`SemanticComponent::composes`]). A prop whose checker
/// type holds an `opaque` part, where the structural type holds none, keeps the structural type and adds the checker's
/// reasons to its `degradedBy`: the checker's answer there is a placeholder, and the structural one is not confirmed,
/// so it is marked. A type the checker only cut at a limit (`truncated`) is still its answer.
///
/// Two facts the checker does not have come from oxc's syntax, read from the files the answer names: a prop's default
/// (the component's code: a destructured parameter's initializer, `defaultProps`; else the checker's `@default` tag)
/// and the order of a union's members (the order its declaration writes them in). The structural answer gives them
/// where the syntax does not tell ([`ResolverFacts::Used`]).
pub fn merge_semantic_props<'a>(
    entry: &mut ComponentEntry,
    props: impl Iterator<Item = &'a Arc<SemanticProp>>,
    composes: Option<&[String]>,
    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
) -> MergedProps {
    let props: Vec<Arc<SemanticProp>> = props.cloned().collect();
    let syntax = SourceSyntax::read(std::iter::once((&*entry, props.as_slice())));
    let merge = Merge { composes, unanswered: Unanswered::Keep, syntax: &syntax, resolver: ResolverFacts::Used };
    let mut merged = replace_props(entry, props.iter(), &merge, shared, &mut MergeMemo::default());
    merged.diagnostics = syntax.diagnostics;
    merged
}

/// The kinds of what the checker could not read in `checker`, when the structural type `structural` read everything:
/// then the structural type is kept and marked with them. Empty when the checker's type is its answer.
fn unread_by_checker(checker: &PropType, structural: &PropType) -> Vec<&'static str> {
    let unread: Vec<&'static str> = checker.degraded_by().into_iter().filter(|kind| *kind != TRUNCATED_KIND).collect();
    if unread.is_empty() || structural.degraded_by().iter().any(|kind| *kind != TRUNCATED_KIND) {
        return Vec::new();
    }
    unread
}

/// The one diagnostic for the props of `affects` that kept their structural type because the checker could not read it
/// ([`MergedProps::unread`]); each such prop says why in its `degradedBy`.
pub(crate) fn unread_diagnostic(props: usize, affects: Vec<String>) -> Diagnostic {
    let mut diagnostic = Diagnostic::new(
        DiagnosticSeverity::Info,
        DiagnosticCode::SemanticBackend,
        format!(
            "{props} prop(s) of {} component(s) keep their structural type: the TypeScript checker could not read it, \
             and their degradedBy says what it could not read",
            affects.len()
        ),
    );
    diagnostic.affects = affects;
    diagnostic
}

/// [`ResolverFacts::NoFallback`]'s diagnostic for the props of `affects` whose checker type holds a part the checker
/// could not read, where the structural type read it all: they keep the checker's `opaque` type.
fn unread_without_fallback(props: usize, affects: Vec<String>) -> Diagnostic {
    let mut diagnostic = Diagnostic::new(
        DiagnosticSeverity::Warning,
        DiagnosticCode::SemanticBackend,
        format!(
            "{props} prop(s) of {} component(s) are opaque: the TypeScript checker could not read their type, the \
             structural fallback is off, and their degradedBy says what it could not read",
            affects.len()
        ),
    );
    diagnostic.affects = affects;
    diagnostic
}

/// [`ResolverFacts::NoFallback`]: every component of `output` the checker did not answer for (`answered`, sorted) keeps
/// its props by name and whether they are required, each typed an `opaque` `unknown` (`unsupportedExpression`) with no
/// default, description or tags, and one warning names the components.
